#include <QtWidgets>
#include <QTemporaryDir>
#include <cmath>
#include <complex>
#include <vector>
#include <algorithm>
#include <stdexcept>

struct V{double x,y,z;V operator+(V b)const{return{x+b.x,y+b.y,z+b.z};}V operator-(V b)const{return{x-b.x,y-b.y,z-b.z};}V operator*(double s)const{return{x*s,y*s,z*s};}};
double dot(V a,V b){return a.x*b.x+a.y*b.y+a.z*b.z;}V norm(V a){double n=std::sqrt(dot(a,a));return a*(1/n);}
double sphere(V o,V d,V c,double r){V t=o-c;double b=dot(t,d),disc=b*b-dot(t,t)+r*r;if(disc<0)return -1;double root=std::sqrt(disc);return -b-root>.001?-b-root:-b+root>.001?-b+root:-1;}
QImage make(const QString&setting){bool ok=true;double lightX=setting.isEmpty()?2:setting.toDouble(&ok);if(!ok||!std::isfinite(lightX)||std::abs(lightX)>5)throw std::runtime_error("Light x is -5..5");QImage image(640,400,QImage::Format_RGB32);V centers[]={{-1,0,4},{1,0,5},{0,-1001,4}};double radii[]={1,1,1000};V colors[]={{.2,.8,.6},{.8,.3,.4},{.65,.65,.7}};V light{lightX,4,-1},origin{0,.5,-3};for(int y=0;y<400;y++)for(int x=0;x<640;x++){V ray=norm({(x-320)/400.,(200-y)/400.,1});double nearest=1e10;int hit=-1;for(int i=0;i<3;i++){double t=sphere(origin,ray,centers[i],radii[i]);if(t>0&&t<nearest){nearest=t;hit=i;}}V color{.08,.14,.23};if(hit>=0){V point=origin+ray*nearest,n=norm(point-centers[hit]),l=norm(light-point);bool shadow=false;for(int i=0;i<3;i++){double t=sphere(point+n*.003,l,centers[i],radii[i]);if(t>0&&t<std::sqrt(dot(light-point,light-point)))shadow=true;}double diffuse=shadow?0:std::max(0.,dot(n,l));double spec=shadow?0:std::pow(std::max(0.,dot(n,norm(l-ray))),32);color=colors[hit]*(.15+.8*diffuse)+V{1,1,1}*(.4*spec);}image.setPixelColor(x,y,QColor::fromRgbF(qBound(0.,color.x,1.),qBound(0.,color.y,1.),qBound(0.,color.z,1.)));}return image;}
bool test(){double t=sphere({0,0,0},{0,0,1},{0,0,5},1);if(std::abs(t-4)>1e-8)return false;if(sphere({0,0,0},{0,1,0},{0,0,5},1)>0)return false;auto image=make("2");return image.width()==640&&image.pixel(320,300)!=image.pixel(0,0);}

int main(int argc,char**argv){if(argc==2&&QString(argv[1])=="--self-test"){QCoreApplication a(argc,argv);return test()?0:1;}QApplication a(argc,argv);QWidget w;w.setWindowTitle("Tiny Raytracer Studio");w.resize(1000,750);auto layout=new QVBoxLayout(&w);layout->addWidget(new QLabel("Three spheres, a ground plane, and direct diffuse/specular lighting."));auto controls=new QHBoxLayout;auto input=new QLineEdit;input->setPlaceholderText("Light horizontal position -5 to 5 (default 2)");controls->addWidget(input);auto render=new QPushButton("Render / analyze");controls->addWidget(render);auto save=new QPushButton("Export PNG");controls->addWidget(save);layout->addLayout(controls);auto view=new QLabel;view->setAlignment(Qt::AlignCenter);layout->addWidget(view,1);QImage image;QObject::connect(render,&QPushButton::clicked,[&](){try{image=make(input->text());view->setPixmap(QPixmap::fromImage(image).scaled(920,600,Qt::KeepAspectRatio));}catch(const std::exception&e){QMessageBox::warning(&w,"Input",e.what());}});QObject::connect(save,&QPushButton::clicked,[&](){if(image.isNull())return;auto p=QFileDialog::getSaveFileName(&w,"Export image",{},"PNG (*.png)");if(!p.isEmpty()&&!image.save(p,"PNG"))QMessageBox::warning(&w,"Export","Write failed");});w.show();return a.exec();}
